function initFaqSections(){document.querySelectorAll(".faq-section").forEach(e=>{e.querySelectorAll(".faq-section__question").forEach(e=>{e.addEventListener("click",()=>{const t=e.closest(".faq-section__item");if(!t)return;const o=t.classList.toggle("is-open");e.setAttribute("aria-expanded",o?"true":"false")})});const t=e.querySelector(".faq-section__load-more-btn");t&&t.addEventListener("click",()=>{const o=parseInt(t.dataset.batchSize,10)||5,n=e.querySelectorAll(".faq-section__item--more");n.forEach((e,t)=>{t<o&&e.classList.remove("faq-section__item--more")}),n.length<=o&&t.closest(".faq-section__load-more").remove()})})}document.addEventListener("DOMContentLoaded",()=>{initFaqSections()});